INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (59, 292, 'color POF Film included POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form', '../upload/image/20180925/20180925213229_39031.jpg', '<p></p><p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Color POF shrinkage cling film (POF film,Polyolefin Shrink Film)</span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;"><strong>Types: color POF Film included POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form </strong></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">FOF film have center fold or single.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">POF Thermal Shrinkable Cling Film (Polyolefin Shrink Film - Center Folded),</span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Types:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">1. POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form,</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Normal size: 19mic x 45cm x 1000Mtr</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Thickness of POF Thermal Shrinkable Cling Film :12-25 microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Width of POF Thermal Shrinkable Cling Film: 100-1500MM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Length of POF Film: 500-3000M Inner core: 3",6",1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">POF shrinkage film, POF FILM,Polyolefin Shrink Film,Shrink Film,POF macro perforated cling film</span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <br/></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;"><strong>2. <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;"><strong>POF Tubular Form cling film ( POF film- Tubular Form )</strong></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Thickness of POF POF Tubular Form heat shrink cling film:15,25,30. microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Width of POF heat shrink cling film: 100-1500MM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Length of POF heat shrink cling film: 500-1500M</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Inner core of POF film in rolls: 3", 6",1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Packing of POF film rolls: inner package in carton and outer packing in pallets</span></strong></span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <br/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (59, 291, 'POF macro perforated cling film ( POF film)', '../upload/image/20180925/20180925213246_12309.jpg', '<p><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">POF macro perforated cling film ( POF film) </span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">POF shrinkage cling film (POF film,Polyolefin Shrink Film) <br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">Thickness of POF heat shrink cling film:12-25 microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">Width of POF heat shrink cling film: 100-1500MM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">Length of POF heat shrink cling film: 500-3000M</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">Inner core of POF film in rolls: 3" , 6" ,1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">Packing of POF film rolls: inner package in carton and outer packing in pallets</span> </span></p> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">POF shrinkage cling film (POF film,Polyolefin Shrink Film)</span></span></p> <p><br/></p> </span> <p><br/></p> </span> <p><br/></p> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (59, 290, 'POF Polyolefin Thermal (heat)Shrinkable Cling Film', '../upload/image/20180925/20180925213302_96591.jpg', '<p></p><div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:12pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>Environmentally-friendly packaging film -</strong></span><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>POF Polyolefin Thermal (heat)Shrinkable Cling Film</strong></span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Types: </span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">1.) </span><span style="font-size:12pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> POF cling shink film -Center Folded (such as: 19mic x 45cm x 1000Mtr,30 mic x 585 mm x 1500 m)</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">2.) POF cling shink film - Tubular Form (such as: 25 mic x 330 mm x 1000 m)</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">3.)</span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">POF macro perforated cling film</span></span> </div> <div align="left" style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Thickness :12-25 microns</span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:black;font-size:12pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Five layers of co-extruded polyolefin stretch POF thermal(heat) shrinkable film, breaking the traditional three-layers co-extruded film and the traditional of hot-stretching process, featuring a higher toughness and higher anti-impact strength in the line of packaging film industry, and it is the most advanced environmentally-friendly plastic packaging material.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Main features:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">High-resolution, glossy transparent, protection, and to prevent products subject to affecting of dust, moisture and odor without the appearance of erosion.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Nice higher anti-crack-toughness and high anti-impact strength, keeping the relatively stable under high temperature and low temperatures, will not be broken, melted, broken ,decomposition and so on, suit for long-distance transportation and packaging of frozen products.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">faster and higher Shrinking rate, applicable to the packaging of various shapes and sizes of products, strong toughness, light weight, thickness uniformity, and economy.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">POF Thermal(heat)shrinkable film used for the beverage, food, medicine, packaging and other chemicals.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Main products: single-layer membrane, folded membrane, small roll specifications,</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Tes