INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (59, 178, 'POF shrinkage cling film (POF film,Polyolefin Shrink Film)', '../upload/image/20180922/20180922163833_58674.jpg', '<p></p><p>POF shrinkage cling film (POF film,Polyolefin Shrink Film)</p> <p>Types: POF Film included POF hest shrink Cling Film and POF macro perforated cling film<br/> FOF film have center fold or single. <br/> POF Thermal Shrinkable Cling Film (Polyolefin Shrink Film - Center Folded), Types: <br/> 1. POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form,<br/> Normal size: 19mic x 45cm x 1000Mtr<br/> Thickness of POF Thermal Shrinkable Cling Film :12-25 microns<br/> Width of POF Thermal Shrinkable Cling Film: 100-1500MM <br/> Length of POF Film: 500-3000M Inner core: 3",6",1.8"<br/> POF shrinkage film, POF FILM,Polyolefin Shrink Film,Shrink Film,POF macro perforated cling film<br/> 2. POF macro perforated cling film ( POF film)<br/> Thickness of POF heat shrink cling film:12-25 microns<br/> Width of POF heat shrink cling film: 100-1500MM <br/> Length of POF heat shrink cling film: 500-3000M <br/> Inner core of POF film in rolls: 3" , 6" ,1.8"<br/> Packing of POF film rolls: inner package in carton and outer packing in pallets<br/> 3. POF Tubular Form cling film ( POF film- Tubular Form )<br/> Thickness of POF POF Tubular Form heat shrink cling film:15,25,30. microns<br/> Width of POF heat shrink cling film: 100-1500MM <br/> Length of POF heat shrink cling film: 500-1500M <br/> Inner core of POF film in rolls: 3", 6",1.8"<br/> Packing of POF film rolls: inner package in carton and outer packing in pallets</p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">POF shrinkage cling film (POF film,Polyolefin Shrink Film)</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Types: POF Film included POF hest shrink Cling Film and POF macro perforated cling film</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> FOF film have center fold or single. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> POF Thermal Shrinkable Cling Film (Polyolefin Shrink Film - Center Folded), </span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Types: </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 1. POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form,</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Normal size: 19mic x 45cm x 1000Mtr</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thickness of POF Thermal Shrinkable Cling Film :12-25 microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Width of POF Thermal Shrinkable Cling Film: 100-1500MM </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Length of POF Film: 500-3000M Inner core: 3",6",1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> POF shrinkage film, POF FILM,Polyolefin Shrink Film,Shrink Film,POF macro perforated cling film</span></p> <p><img alt="" src="../upload/image/20180828/20180828122537_20071.png"/><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 2. POF macro perforated cling film ( POF film)</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thickness of POF heat shrink cling film:12-25 microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Width of POF heat shrink cling film: 100-1500MM </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Length of POF heat shrink cling film: 500-3000M </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Inner core of POF film in rolls: 3" , 6" ,1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Packing of POF film rolls: inner package in carton and outer packing in pallets</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 3. POF Tubular Form cling film ( POF film- Tubular Form )</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thickness of POF POF Tubular Form heat shrink cling film:15,25,30. microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Width of POF heat shrink cling film: 100-1500MM </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Length of POF heat shrink cling film: 500-1500M </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Inner core of POF film in rolls: 3", 6",1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Packing of POF film rolls: inner package in carton and outer packing in pallets</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><img alt="" src="../upload/image/20180828/20180828122613_33348.jpg"/><img alt="" src="../upload/image/20180828/20180828122613_66074.jpg"/></span></p>', '2026-09-06 20:58:45');